import{_ as a,c as t,o as r,a2 as o}from"./chunks/framework.mqLGQ42V.js";const p=JSON.parse('{"title":"标签系统 (Tagging) - Rive 编辑器","description":"编辑器 (Editor) 标签是一种进一步组织层级面板的方法。通过创建标签并将其应用到 层级面板 (Hierarchy) 中的对象（如骨骼或分组），你可以根据需要在特定时刻过滤视图，聚焦于关键内容。","frontmatter":{"title":"标签系统 (Tagging) - Rive 编辑器","description":"编辑器 (Editor) 标签是一种进一步组织层级面板的方法。通过创建标签并将其应用到 层级面板 (Hierarchy) 中的对象（如骨骼或分组），你可以根据需要在特定时刻过滤视图，聚焦于关键内容。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 标签系统"}]]},"headers":[],"relativePath":"editor/tagging.md","filePath":"editor/tagging.md","lastUpdated":1774867914000}'),i={name:"editor/tagging.md"};function l(n,e,s,g,c,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<p>编辑器 (Editor)</p><h1 id="标签系统-tagging" tabindex="-1">标签系统 (Tagging) <a class="header-anchor" href="#标签系统-tagging" aria-label="Permalink to &quot;标签系统 (Tagging)&quot;">​</a></h1><p>标签是一种进一步组织层级面板的方法。通过创建标签并将其应用到 <a href="/docs/editor/interface-overview/hierarchy">层级面板 (Hierarchy)</a> 中的对象（如骨骼或分组），你可以根据需要在特定时刻过滤视图，聚焦于关键内容。</p><h2 id="​-创建标签-creating-tags" tabindex="-1"><a href="#creating-tags">​</a> 创建标签 (Creating Tags) <a class="header-anchor" href="#​-创建标签-creating-tags" aria-label="Permalink to &quot;[​](#creating-tags) 创建标签 (Creating Tags)&quot;">​</a></h2><p>有两种创建标签的方式：通过层级面板或使用检查器。请记住，创建的任何标签都可以在该文件的任何画板中使用。</p><h3 id="​-在检查器中" tabindex="-1"><a href="#in-the-inspector">​</a> 在检查器中 <a class="header-anchor" href="#​-在检查器中" aria-label="Permalink to &quot;[​](#in-the-inspector) 在检查器中&quot;">​</a></h3><p>确保舞台上未选中任何内容，然后在检查器中找到 <strong>Tags</strong> 选项并点击旁边的加号。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 通过检查器创建标签) 标签添加后，你可以根据喜好修改名称和颜色。</p></blockquote><h3 id="​-在层级面板中" tabindex="-1"><a href="#in-the-hierarchy">​</a> 在层级面板中 <a class="header-anchor" href="#​-在层级面板中" aria-label="Permalink to &quot;[​](#in-the-hierarchy) 在层级面板中&quot;">​</a></h3><ul><li><strong>方式一</strong>：使用层级面板顶部的标签菜单。在这里你可以新建标签、编辑现有标签、折叠标签视图、过滤、锁定或选择指定的标签。</li></ul><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 通过标签菜单创建标签)</p></blockquote><ul><li><strong>方式二</strong>：选中一个或多个对象，鼠标右键点击并选择“Add Tag”选项。你可以创建新标签或分配已存在的标签。</li></ul><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 在对象上直接创建标签)</p></blockquote><h2 id="​-标签菜单-the-tags-menu" tabindex="-1"><a href="#the-tags-menu">​</a> 标签菜单 (The Tags Menu) <a class="header-anchor" href="#​-标签菜单-the-tags-menu" aria-label="Permalink to &quot;[​](#the-tags-menu) 标签菜单 (The Tags Menu)&quot;">​</a></h2><p>标签菜单是大多数标签选项所在地。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 标签菜单概览)</p></blockquote><h3 id="​-折叠标签-collapse-tag" tabindex="-1"><a href="#collapse-tag">​</a> 折叠标签 (Collapse Tag) <a class="header-anchor" href="#​-折叠标签-collapse-tag" aria-label="Permalink to &quot;[​](#collapse-tag) 折叠标签 (Collapse Tag)&quot;">​</a></h3><p>当你为对象添加标签时，标签名称和颜色图标通常显示在右侧。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 标签显示效果) 你可以使用 <strong>Collapse Tag</strong> 选项隐藏名称（仅保留颜色点），或使用 Reveal Tag 重新显示。</p></blockquote><h3 id="​-过滤标签-filter-tags" tabindex="-1"><a href="#filter-tags">​</a> 过滤标签 (Filter Tags) <a class="header-anchor" href="#​-过滤标签-filter-tags" aria-label="Permalink to &quot;[​](#filter-tags) 过滤标签 (Filter Tags)&quot;">​</a></h3><p>当鼠标悬停在菜单中的某个标签上时，会出现 <strong>Filter (过滤)</strong> 选项。这会过滤你的层级树，仅显示拥有该标签的对象。当前激活的过滤器会显示在菜单旁。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 过滤标签示例) 你可以将多个标签添加到过滤器中，这在制作动画时仅显示所需的交互控制项非常有用。</p></blockquote><h3 id="​-锁定-locked" tabindex="-1"><a href="#locked">​</a> 锁定 (Locked) <a class="header-anchor" href="#​-锁定-locked" aria-label="Permalink to &quot;[​](#locked) 锁定 (Locked)&quot;">​</a></h3><p><strong>Locked</strong> 选项允许你锁定带有所选标签的对象。锁定后，你无法在舞台上直接选中该对象。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 锁定标签示例) 当你想把文件交付给另一名动画师，且不想让他们误操作某些关键控制器时，这是一个极好的工具。该选项也可在检查器的锁定图标处找到。</p></blockquote><h3 id="​-选择-select" tabindex="-1"><a href="#select">​</a> 选择 (Select) <a class="header-anchor" href="#​-选择-select" aria-label="Permalink to &quot;[​](#select) 选择 (Select)&quot;">​</a></h3><p><strong>Select</strong> 选项会一键选中所有带有该标签的对象。该选项也可在检查器的目标图标处找到。</p><p><a href="https://help.rive.app/editor/mcp/integration" target="_blank" rel="noreferrer">MCP 集成 (MCP Integration)</a></p>',28)])])}const u=a(i,[["render",l]]);export{p as __pageData,u as default};
